<script setup lang="ts">
const {t}=useI18n(),{roleLabel}=useOptionLabel(),{bizErrorMessage}=useBizError(),staff=useStaffStore()
const roles=ref<any[]>([]),permissions=ref<any[]>([]),selected=ref<number|null>(null),creating=ref(false),loading=ref(false),saving=ref(false),error=ref(''),keyword=ref(''),ready=ref(false),original=ref('')
const form=reactive({display_name:'',description:'',is_active:true,permissions:[] as number[],revision:0})
const record=computed(()=>roles.value.find(row=>row.id===selected.value))
const canEdit=computed(()=>ready.value&&!!staff.staffInfo&&staff.hasPermission('company_roles_edit'))
const editable=computed(()=>canEdit.value&&(creating.value||!!record.value&&!record.value.readonly&&record.value.assignable))
const dirty=computed(()=>editable.value&&!!original.value&&JSON.stringify(form)!==original.value)
useUnsavedForm(()=>dirty.value,()=>saving.value||loading.value)
const visiblePermissions=computed(()=>editable.value?permissions.value.filter(row=>row.grantable):permissions.value)
const display=(row:any)=>row.company_id?row.display_name:roleLabel(row.name)
const filtered=computed(()=>roles.value.filter(row=>(display(row)+' '+(row.description||'')).toLowerCase().includes(keyword.value.toLowerCase())))
let generation=0,changing=false
const discard=async()=>!dirty.value||await wConfirm({title:t('unsaved-form.title'),message:t('unsaved-form.message'),confirmText:t('unsaved-form.leave'),cancelText:t('unsaved-form.stay')})
const apply=(row:any)=>{creating.value=false;selected.value=row.id;Object.assign(form,{display_name:display(row),description:row.description||'',is_active:row.is_active,revision:row.revision,permissions:permissions.value.filter(p=>row.permissions.includes('company_all_access')||row.permissions.includes(p.name)).map(p=>p.id)});original.value=JSON.stringify(form)}
const select=async(row:any)=>{if(saving.value||loading.value||changing||(!creating.value&&selected.value===row.id))return;changing=true;try{if(await discard()){error.value='';apply(row)}}finally{changing=false}}
const load=async()=>{
 if(saving.value||changing)return
 changing=true
 try{if(!await discard())return
  const seq=++generation;loading.value=true;error.value='';ready.value=false
  const current=await staff.getCurrentStaffInfo();if(seq!==generation)return
  if(!current){roles.value=[];permissions.value=[];selected.value=null;creating.value=false;error.value=t('common.validation.company-required');return}
  const results=await Promise.all([httpRequest<any>('/api/warehouse/company/roles',{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}),httpRequest<any>('/api/warehouse/company/roles/permissions',{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}})])
  if(seq!==generation)return
  roles.value=results[0]?.items||[];permissions.value=results[1]?.items||[];ready.value=!!results[0]&&!!results[1];creating.value=false
  if(ready.value){const row=roles.value.find(row=>row.id===selected.value)||roles.value[0];if(row)apply(row);else selected.value=null}else{roles.value=[];selected.value=null}
 }finally{loading.value=false;changing=false}
}
const create=async()=>{if(saving.value||loading.value||changing||!canEdit.value)return;changing=true;try{if(!await discard())return;creating.value=true;selected.value=null;error.value='';Object.assign(form,{display_name:'',description:'',is_active:true,permissions:[],revision:0});original.value=JSON.stringify(form)}finally{changing=false}}
const save=async()=>{if(saving.value||!editable.value||loading.value)return;saving.value=true;error.value='';try{const result=await httpRequest<any>('/api/warehouse/company/roles'+(creating.value?'':'/'+selected.value),{method:creating.value?'POST':'PUT',body:{...form,display_name:form.display_name.trim()},onError:e=>error.value=bizErrorMessage(e)});if(result){original.value=JSON.stringify(form);selected.value=result.id;creating.value=false;saving.value=false;await load();showToast(t('action-results.success'),'success')}}finally{saving.value=false}}
const remove=async()=>{if(saving.value||loading.value||!editable.value||!record.value||record.value.users>0)return;saving.value=true;error.value='';try{if(!await showConfirm(t('action-results.delete-confirm-title'),t('action-results.delete-confirm',{entity:t('common.entities.role')}),t('button.confirm'),t('button.cancel')))return;const result=await httpRequest<any>('/api/warehouse/company/roles/'+record.value.id,{method:'DELETE',body:{revision:record.value.revision},onError:e=>error.value=bizErrorMessage(e)});if(result){original.value='';selected.value=null;saving.value=false;await load()}}finally{saving.value=false}}
onMounted(load);onBeforeUnmount(()=>generation++)
useHead({title:()=>t('company-roles.title')})
</script>
<template><div class="company-roles w-scope"><header><div><h1>{{t('company-roles.title')}}</h1><p>{{t('company-roles.hint')}}</p></div><WButton v-if="canEdit" variant="primary" :disabled="saving||loading" @click="create">{{t('company-roles.create')}}</WButton></header><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton :disabled="saving" @click="load">{{t('freight.reload')}}</WButton></template></WAlert>
 <div class="role-grid"><WCard flush><div class="search"><WInput v-model="keyword" type="search" :aria-label="t('common.search')" :placeholder="t('common.search')"/></div><nav class="role-list" :aria-label="t('company-roles.title')"><button v-for="row in filtered" :key="row.id" class="role-link" :class="{selected:row.id===selected}" :disabled="saving||loading" @click="select(row)"><strong>{{display(row)}}</strong><WStatus v-if="!row.is_active" tone="none">{{t('company-roles.disabled')}}</WStatus><small>{{row.readonly?t('company-roles.builtin')+' \u00b7 ':''}}{{t('admin-role-scope.usage',{users:row.users,permissions:row.permissions.length})}}</small></button><WEmptyState v-if="!loading&&!error&&!filtered.length" :title="t('company-roles.empty')"/></nav></WCard>
 <WCard v-if="creating||record" flush><form @submit.prevent="save"><div class="form-heading"><h2>{{creating?t('company-roles.create'):display(record)}}</h2><span v-if="record?.readonly" class="builtin">{{t('company-roles.builtin')}}</span></div><p v-if="record?.readonly" class="builtin-note">{{t(record.permissions.includes('company_all_access')?'company-roles.all-access':'company-roles.builtin-hint')}}</p><fieldset :disabled="!editable||saving||loading"><div class="fields"><WField :label="t('common.entities.role')" required><WInput v-model="form.display_name" maxlength="80" required/></WField><WField :label="t('common.fields.description')"><WInput v-model="form.description" maxlength="255"/></WField><WSwitch v-model="form.is_active">{{t('recipient.ui.enable')}}</WSwitch></div><PermissionSelector matrix v-model="form.permissions" :all-permissions="visiblePermissions"/></fieldset><footer><WButton v-if="editable&&!creating" variant="danger" :disabled="saving||record?.users>0" @click="remove">{{t('button.delete')}}</WButton><span v-if="record?.users>0&&!record?.readonly" class="assigned-note">{{t('company-roles.assigned')}}</span><WButton :disabled="saving||loading" @click="creating?create():load()">{{t('button.reset')}}</WButton><WButton v-if="editable" type="submit" variant="primary" :loading="saving">{{t('button.save')}}</WButton></footer></form></WCard><WCard v-else><WEmptyState :title="loading?t('common.status.loading'):t('company-roles.empty')"/></WCard></div></div></template>
<style scoped>.company-roles{display:flex;flex-direction:column;gap:16px}header{display:flex;justify-content:space-between;align-items:start;gap:12px}h1{font-size:24px;margin:0}p{color:var(--w-text-3);font-size:13px}.role-grid{display:grid;grid-template-columns:256px minmax(0,1fr);gap:16px;align-items:start}.search{padding:12px;border-bottom:1px solid var(--w-border)}.role-list{display:flex;flex-direction:column;padding:8px;gap:2px}.role-link{border:0;background:none;text-align:left;padding:8px 12px;display:flex;flex-wrap:wrap;gap:4px 8px;border-radius:6px;cursor:pointer;color:var(--w-text-1)}.role-link.selected{background:#f5f4ff;color:#4e1dbc}.role-link strong{font-size:14px;overflow-wrap:anywhere;min-width:0}.role-link small{width:100%;color:var(--w-text-3)}.form-heading{display:flex;flex-wrap:wrap;overflow-wrap:anywhere;gap:12px;align-items:center;padding:16px 24px 4px}h2{font-size:16px;margin:0}.builtin{font-size:12px;border:1px solid var(--w-border);border-radius:6px;padding:2px 6px}.builtin-note{padding:0 24px}fieldset{border:0;padding:0;min-width:0}.fields{display:grid;grid-template-columns:1fr 2fr;gap:12px 16px;padding:16px 24px}.fields>.w-switch{grid-column:1/-1}footer{display:flex;flex-wrap:wrap;justify-content:flex-end;align-items:center;gap:8px;padding:16px 24px;border-top:1px solid var(--w-border)}.assigned-note{font-size:12px;color:var(--w-text-3)}@media(max-width:1100px){.role-grid{grid-template-columns:1fr}.role-list{max-height:240px;overflow:auto}}@media(max-width:600px){.fields{grid-template-columns:1fr}header{flex-wrap:wrap}}</style>
